/**
 * The language switch changes this device at once and, when signed in, saves the choice to
 * the account without ever sending the visitor to /login.
 *
 * Value: protects=the switch flips the interface, saves to /auth/me only inside the signed-in app, with
 * stayOnUnauthorized, and survives a failed save; fails_when=saveToAccount is dropped, runs
 * signed out, or loses stayOnUnauthorized; why_new=no test rendered LanguageToggle; seam=none
 * Generated by /ship test coverage audit (pass 1).
 */
import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { I18nProvider, useTranslation } from "@/lib/i18n";
import { translate } from "@/lib/translate";
import { LanguageToggle } from "./language-toggle";

const mockPut = jest.fn();
jest.mock("@/lib/api-client", () => ({ api: { put: (...args: unknown[]) => mockPut(...args) } }));

function Shown() {
  const { locale } = useTranslation();
  return <p data-testid="locale">{locale}</p>;
}

function renderToggle({ persist = false }: { persist?: boolean } = {}) {
  render(
    <I18nProvider initialLocale="en">
      <LanguageToggle persist={persist} />
      <Shown />
    </I18nProvider>
  );
  return userEvent.setup();
}

beforeEach(() => {
  mockPut.mockReset().mockResolvedValue({});
  localStorage.clear();
  // setLocale writes these too: reset them so no test passes on a previous one's switch
  document.documentElement.lang = "en";
  document.title = "";
  document.cookie = "locale=; max-age=0; path=/";
});

describe("LanguageToggle", () => {
  it("switches a signed-out visitor without calling the API", async () => {
    const user = renderToggle();

    await user.click(screen.getByRole("button", { name: "Passer en français" }));

    expect(screen.getByTestId("locale")).toHaveTextContent("fr");
    expect(document.documentElement.lang).toBe("fr");
    expect(mockPut).not.toHaveBeenCalled();
    expect(screen.getByRole("button", { name: "Switch to English" })).toBeInTheDocument();
  });

  // Value: protects=the switch leaves the cookie proxy.ts reads on the next page load, and the tab
  // title in the new language; fails_when=setLocale stops calling writeLocaleCookie or updating
  // document.title; why_new=no test asserted setLocale's side effects; seam=none
  it("remembers the choice for the next page load and retitles the tab", async () => {
    const user = renderToggle();

    await user.click(screen.getByRole("button", { name: "Passer en français" }));

    expect(document.cookie).toContain("locale=fr");
    expect(document.title).toBe(translate("fr", "meta.title"));
    expect(document.title).not.toBe(translate("en", "meta.title"));
  });

  // Regression: ISSUE-006 — on a shared device, the switch on a public page wrote the visitor's
  // choice into the account of whoever left a token behind
  // Found by the /ship adversarial review on 2026-10-02 (finding #2, language-toggle.tsx).
  // Red proof: this test failed against c1cb316 (the toggle saved whenever a token existed)
  // and passes from ee9af73, which added the `persist` prop.
  it("never saves to an account from a public page, even with a token left on the device", async () => {
    localStorage.setItem("token", "someone-elses");
    const user = renderToggle();

    await user.click(screen.getByRole("button", { name: "Passer en français" }));

    expect(screen.getByTestId("locale")).toHaveTextContent("fr");
    expect(mockPut).not.toHaveBeenCalled();
  });

  it("saves the choice to the account inside the signed-in app, staying on the page on a 401", async () => {
    localStorage.setItem("token", "t");
    const user = renderToggle({ persist: true });

    await user.click(screen.getByRole("button", { name: "Passer en français" }));

    expect(mockPut).toHaveBeenCalledWith("/auth/me", { locale: "fr" }, { stayOnUnauthorized: true });
  });

  it("keeps the new language when saving it fails", async () => {
    localStorage.setItem("token", "t");
    mockPut.mockRejectedValue(new Error("offline"));
    const user = renderToggle({ persist: true });

    await user.click(screen.getByRole("button", { name: "Passer en français" }));

    expect(screen.getByTestId("locale")).toHaveTextContent("fr");
  });
});
